  const expected = createHmac("sha256", SECRET).update(`${NOW}.`).update(raw).digest("hex");
  assert.equal(computeSignature(SECRET, NOW, raw), expected);
  const header = `t=${NOW},v1=${"0".repeat(64)},v1=${expected}`;
  assert.doesNotThrow(() => verifyWebhook(raw, header, ["old-secret", SECRET], NOW));
  assert.doesNotThrow(() => verifyWebhook(raw, signed(raw), [SECRET, "next-secret"], NOW));
  assert.throws(() => verifyWebhook(raw.toString().trim(), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(raw, header, [], NOW), SignatureError);
  const bytes = Buffer.from([0xff, 0x00, 0x80]);
  assert.doesNotThrow(() => verifyWebhook(bytes, signed(bytes), [SECRET], NOW));
  assert.throws(() => verifyWebhook(bytes.toString("utf8"), signed(bytes), [SECRET], NOW), SignatureError);
});

test("timestamp tolerance is inclusive in both directions", () => {
  const raw = JSON.stringify(event("evt_clock"));
  for (const offset of [-300, 0, 300]) {
    assert.doesNotThrow(() => verifyWebhook(raw, signed(raw, NOW + offset), [SECRET], NOW));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook(raw, signed(raw, NOW + offset), [SECRET], NOW), SignatureError);
  }
  assert.throws(() => verifyWebhook(raw, signed(raw, NOW + 11), [SECRET], NOW, 10), SignatureError);
});

test("missing and malformed signature headers fail closed", () => {
  const raw = JSON.stringify(event("evt_headers"));
  for (const header of [undefined, "", "v1=" + "a".repeat(64), `t=${NOW}`, `t=${NOW},v1=nope`,
    `t=${NOW},v1=${"A".repeat(64)}`, `t=${NOW},t=${NOW},v1=${"0".repeat(64)}`,
    `t=999999999999999999999999,v1=${"0".repeat(64)}`]) {
    assert.throws(() => verifyWebhook(raw, header, [SECRET], NOW), SignatureError);
  }
});

test("configured policy honors the inclusive INR-only finance threshold", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 500000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
});

test("invalid events fail validation; unhandled types need no refund data", () => {
  for (const raw of ["{", "null", "[]", "{}", JSON.stringify({ ...event("evt"), created: "bad" }),
    JSON.stringify(event("evt", "refund.requested", 0)),
    JSON.stringify({ ...event("evt"), data: { refund_id: "rf", amount: 1, currency: "" } })]) {
    assert.throws(() => parseEvent(raw), EventError);
  }
  assert.equal(parseEvent(JSON.stringify({ event_id: "evt_unknown", type: "payment.updated", created: NOW })).type,
    "payment.updated");
});

test("dedup persists across restart and never changes refunds, raw events, or audits", (t) => {
  const dir = mkdtempSync(join(tmpdir(), "pay381-store-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const store = new Store(dir);
  for (const id of ["evt_persist", "constructor", "__proto__"]) {
    const ev = event(id);
    assert.equal(processEvent(store, POLICY, ev).outcome, "processed");
    const before = snapshot(dir);
    assert.equal(processEvent(new Store(dir), POLICY, { ...ev, data: { ...ev.data, amount: 1 } }).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
  }
  assert.equal(new Store(dir).listRefunds().length, 3);
});

test("cancellations and ignored events are idempotent, including ignored auto-approved cancellations", (t) => {
  const dir = mkdtempSync(join(tmpdir(), "pay381-cancel-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const store = new Store(dir);
  processEvent(store, POLICY, event("evt_request", "refund.requested", 500001));
  const cancel = event("evt_cancel", "refund.cancelled");
  processEvent(store, POLICY, cancel);
  assert.equal(store.listRefunds()[0].status, "cancelled");
  let before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, cancel).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  const auto = event("evt_auto");
  auto.data.refund_id = "rf_auto";
  processEvent(store, POLICY, auto);
  const ignore = { ...event("evt_ignore", "refund.cancelled"), data: { ...auto.data } };
  assert.equal(processEvent(store, POLICY, ignore).outcome, "ignored");
  before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, ignore).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  const unknown = parseEvent(JSON.stringify({ event_id: "evt_unhandled", type: "payment.updated", created: NOW }));
  assert.equal(processEvent(store, POLICY, unknown).outcome, "ignored");
  before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, unknown).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
});

